def simulate_tournament(draw, P, rng):
    survivors = list(draw)
    while len(survivors) > 1:
        next_round = []
        for (i, j) in pair_up(survivors):
            winner = i if rng.uniform() < P[i, j] else j
            next_round.append(winner)
        survivors = next_round
    return survivors[0]   # champion
